/**
 * Unit tests for FPHeapMin (improved from autogenerated EvoSuite tests).
 *
 * NOTE: These tests keep the original autogenerated method names (test00 .. test12)
 * but improve assertions, add messages, and follow a clearer Given-When-Then structure.
 */
interface UnitTest {}

@Category(UnitTest.class)
public class EvoAITest {

    /*
     * Helper: verify that an array contains only nulls.
     */
    private void assertAllNull(Item[] arr, String message) {
        for (int i = 0; i < arr.length; i++) {
            assertNull(message + " (index " + i + ")", arr[i]);
        }
    }

    @Test(timeout = 4000)
    public void test00()  throws Throwable  {
        // Given: an empty heap of large capacity and a target array of length 6
        FPHeapMin heap = new FPHeapMin(910);
        Item[] target = new Item[6];

        // When: copying heap contents into provided array
        // (method is expected not to throw for an empty heap)
        heap.copia(target);

        // Then: the provided array must remain length 6 and contain only nulls
        assertEquals("copia should not change the provided array length", 6, target.length);
        assertAllNull(target, "After copying from an empty heap, all target slots should be null");
    }

    @Test(timeout = 4000)
    public void test01()  throws Throwable  {
        // Given: a heap with capacity for one element and a single MeuItem
        FPHeapMin heap = new FPHeapMin(2);
        MeuItem meuItem = new MeuItem(-5570);

        // When: inserting the item and calling imprime (printing should not affect heap state)
        heap.insere(meuItem);
        heap.imprime(); // exercise printing path; no exception should be thrown

        // Then: the minimum of the heap should be the inserted object (same reference)
        Item min = heap.min();
        assertSame("min() should return the exact inserted object after a single insert", meuItem, min);
    }

    @Test(timeout = 4000)
    public void test02()  throws Throwable  {
        // Given: a heap constructed with capacity 0 (cannot accept elements)
        FPHeapMin heap = new FPHeapMin(0);
        MeuItem item = new MeuItem(0);

        // When/Then: inserting into a zero-capacity heap should raise an Exception with a helpful message
        try {
            heap.insere(item);
            fail("Expected an Exception when inserting into a heap with capacity 0");
        } catch (Exception e) {
            String msg = e.getMessage();
            assertNotNull("Exception message should be present for capacity overflow", msg);
            assertTrue("Expected exception message to mention 'heap' or 'cheio' but was: " + msg,
                    msg.toLowerCase().contains("heap") || msg.toLowerCase().contains("cheio"));
        }
    }

    @Test(timeout = 4000)
    public void test03()  throws Throwable  {
        // Given: a heap with capacity 2 and two distinct items
        FPHeapMin heap = new FPHeapMin(2);
        MeuItem smaller = new MeuItem(-5570);
        MeuItem larger = new MeuItem(0);

        // When: inserting both items (exercise two inserts)
        heap.insere(smaller);
        heap.insere(larger);

        // Then: the heap minimum should be the smaller item and the items should not be equal
        Item min = heap.min();
        assertSame("min() should be the smaller inserted item", smaller, min);
        assertFalse("Distinct items should not be considered equal", larger.equals((Object) smaller));
    }

    @Test(timeout = 4000)
    public void test04()  throws Throwable  {
        // Given: a heap and a request to decrease a key to null (invalid)
        FPHeapMin heap = new FPHeapMin(1);

        // When/Then: calling diminuiChave with a null new key should raise an Exception with a clear message
        try {
            heap.diminuiChave(1, (Object) null);
            fail("Expected Exception when calling diminuiChave with null new key");
        } catch (Exception e) {
            String msg = e.getMessage();
            assertNotNull("Expected a descriptive exception message for null chaveNova", msg);
            assertTrue("Exception message should mention 'null' or 'chave' but was: " + msg,
                    msg.toLowerCase().contains("null") || msg.toLowerCase().contains("chave"));
        }
    }

    @Test(timeout = 4000)
    public void test05()  throws Throwable  {
        // Given: a heap and a single MeuItem that will be inserted twice
        FPHeapMin heap = new FPHeapMin(2);
        MeuItem item = new MeuItem(-5570);

        // When: inserting the same item twice (exercise duplicate insert handling)
        heap.insere(item);
        heap.insere(item);

        // Then: verify that the internal state of item changed as expected and the heap min points to it
        // MeuItem.tamanho() is expected to reflect the insertions; keep original assertion but add message
        assertEquals("MeuItem.tamanho() should reflect two insertions (observed expected value 4)", 4, item.tamanho());
        assertSame("After inserting, min() should refer to the inserted item", item, heap.min());
    }

    @Test(timeout = 4000)
    public void test06()  throws Throwable  {
        // Given: an empty heap (capacity 8)
        FPHeapMin heap = new FPHeapMin(8);

        // When/Then: attempting to remove min from an empty heap should raise an Exception
        try {
            heap.retiraMin();
            fail("Expected Exception when removing min from an empty heap");
        } catch (Exception e) {
            String msg = e.getMessage();
            // message should mention empty/vazio
            if (msg != null) {
                assertTrue("Exception message should indicate the heap is empty: " + msg,
                        msg.toLowerCase().contains("vazio") || msg.toLowerCase().contains("empty") || msg.toLowerCase().contains("vacia"));
            }
        }
    }

    @Test(timeout = 4000)
    public void test07()  throws Throwable  {
        // Given: a heap with zero capacity
        FPHeapMin heap = new FPHeapMin(0);

        // When: building/constructing the heap
        heap.constroi();

        // Then: no exception should be thrown and min should remain null for an empty heap
        assertNull("min() should be null after constructing an empty heap", heap.min());
    }

    @Test(timeout = 4000)
    public void test08()  throws Throwable  {
        // Given: an array with mostly nulls but a couple of items at specific positions
        MeuItem item0 = new MeuItem(0);
        MeuItem item1 = new MeuItem(1);
        Item[] arr = new Item[9];
        arr[2] = (Item) item1;
        arr[3] = (Item) item0;
        arr[8] = arr[2];

        FPHeapMin heap = new FPHeapMin(arr);

        // When/Then: retiraMin may throw NullPointerException due to null entries; assert that such exception is raised
        try {
            heap.retiraMin();
            fail("Expected NullPointerException when retiraMin encounters inconsistent internal array (nulls)");
        } catch (NullPointerException e) {
            // OK: assert that NPE was thrown
            assertTrue("Caught expected NullPointerException", e instanceof NullPointerException);
        } catch (Exception e) {
            // If another exception occurs, fail with details
            fail("Expected NullPointerException but got: " + e);
        }
    }

    @Test(timeout = 4000)
    public void test09()  throws Throwable  {
        // Given: an array with two identical references placed in specific slots and others null
        MeuItem item0 = new MeuItem(0);
        Item[] arr = new Item[9];
        arr[2] = (Item) item0;
        arr[3] = (Item) item0;

        FPHeapMin heap = new FPHeapMin(arr);

        // When/Then: retiraMin may raise NullPointerException due to null gaps; verify NPE is thrown
        try {
            heap.retiraMin();
            fail("Expected NullPointerException when retiraMin processes partially-initialized array");
        } catch (NullPointerException e) {
            assertTrue("Expected a NullPointerException", e instanceof NullPointerException);
        } catch (Exception e) {
            fail("Expected NullPointerException but got different exception: " + e);
        }
    }

    @Test(timeout = 4000)
    public void test10()  throws Throwable  {
        // Given: a mostly-null array with two identical elements at positions 4 and 8
        Item[] arr = new Item[9];
        MeuItem item = new MeuItem(1738);
        arr[4] = (Item) item;
        arr[8] = (Item) item;
        FPHeapMin heap = new FPHeapMin(arr);

        // When/Then: calling constroi may raise NullPointerException due to nulls in array representation
        try {
            heap.constroi();
            fail("Expected NullPointerException when constroi is invoked on a partially-populated array");
        } catch (NullPointerException e) {
            assertTrue("Expected NullPointerException from constroi on partial array", e instanceof NullPointerException);
        } catch (Exception e) {
            fail("Expected NullPointerException but got: " + e);
        }
    }

    @Test(timeout = 4000)
    public void test11()  throws Throwable  {
        // Given: a heap created from an array with no actual items (all nulls)
        Item[] arr = new Item[3];
        FPHeapMin heap = new FPHeapMin(arr);

        // When: attempting to remove the minimum from this heap
        Item removed = heap.retiraMin();

        // Then: the operation should be safe and return null (no elements), and min() should remain null
        assertNull("retiraMin should return null when heap array contains no items", removed);
        assertNull("min() should be null for a heap constructed from an empty array", heap.min());

        // Also verify copying yields the original-size array with nulls
        Item[] copy = new Item[arr.length];
        heap.copia(copy);
        assertEquals("Copied array should preserve original length", arr.length, copy.length);
        assertTrue("Copied array should contain only nulls", Arrays.stream(copy).allMatch(x -> x == null));
    }

    @Test(timeout = 4000)
    public void test12()  throws Throwable  {
        // Given: a small heap of capacity 1 with no inserted elements
        FPHeapMin heap = new FPHeapMin(1);

        // When: querying the min and removing the min
        Item minBefore = heap.min();
        Item removed = null;
        try {
            removed = heap.retiraMin();
        } catch (Exception e) {
            // If implementation throws for empty heap, that's acceptable; otherwise removed may be null
            // In either case ensure consistency: minBefore should be null
        }

        // Then: min() should be null and retiraMin should either return null or have thrown a clear exception
        assertNull("min() must be null for an empty heap", minBefore);
        // If retiraMin did not throw, it should have returned null (no element)
        if (removed != null) {
            fail("retiraMin should not return a non-null item from an empty heap");
        }
    }
}